CREATE TABLE estrus_record(estrus_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,cattle_id BIGINT NOT NULL,estrus_time DATETIME NOT NULL,symptoms VARCHAR(500),suggestion VARCHAR(255),recorder_id BIGINT NOT NULL,is_void TINYINT NOT NULL DEFAULT 0,void_reason VARCHAR(255),voided_by BIGINT,voided_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version INT NOT NULL DEFAULT 0,INDEX idx_estrus_cattle_date(farm_id,cattle_id,estrus_time));
CREATE TABLE breeding_record(breeding_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,cattle_id BIGINT NOT NULL,breeding_date DATETIME NOT NULL,breeding_method VARCHAR(30) NOT NULL,semen_or_bull VARCHAR(100),breeding_times INT NOT NULL DEFAULT 1,operator_id BIGINT NOT NULL,remark VARCHAR(500),is_void TINYINT NOT NULL DEFAULT 0,void_reason VARCHAR(255),voided_by BIGINT,voided_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version INT NOT NULL DEFAULT 0,INDEX idx_breeding_cattle_date(farm_id,cattle_id,breeding_date));
CREATE TABLE pregnancy_check(check_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,cattle_id BIGINT NOT NULL,breeding_id BIGINT NULL,check_date DATETIME NOT NULL,check_result VARCHAR(30) NOT NULL,expected_calving_date DATE NULL,checker_id BIGINT NOT NULL,remark VARCHAR(500),is_void TINYINT NOT NULL DEFAULT 0,void_reason VARCHAR(255),voided_by BIGINT,voided_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version INT NOT NULL DEFAULT 0,INDEX idx_pregnancy_cattle_date(farm_id,cattle_id,check_date),INDEX idx_pregnancy_due(farm_id,expected_calving_date));
CREATE TABLE calving_record(calving_id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,dam_cattle_id BIGINT NOT NULL,pregnancy_check_id BIGINT NULL,calving_date DATETIME NOT NULL,difficulty_level VARCHAR(30),calf_count INT NOT NULL DEFAULT 1,alive_count INT NOT NULL DEFAULT 0,dam_condition VARCHAR(100),operator_id BIGINT NOT NULL,remark VARCHAR(500),is_void TINYINT NOT NULL DEFAULT 0,void_reason VARCHAR(255),voided_by BIGINT,voided_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version INT NOT NULL DEFAULT 0,INDEX idx_calving_dam_date(farm_id,dam_cattle_id,calving_date));
CREATE TABLE calving_calf_relation(id BIGINT PRIMARY KEY,farm_id BIGINT NOT NULL,calving_id BIGINT NOT NULL,calf_cattle_id BIGINT NOT NULL,birth_order INT,birth_weight DECIMAL(8,2),survival_status VARCHAR(20) NOT NULL DEFAULT 'ALIVE',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_calving_calf UNIQUE(calving_id,calf_cattle_id),INDEX idx_calving_calf(farm_id,calf_cattle_id));
